# 서비스는 OpenAI 형식 하나로 부르고, 라우터가 모델 이름으로 공급자를 찾아 번역하고 비용을 남긴다 (가상 값)
ROUTES = {
    "gpt-oss-120b": {"provider": "self-hosted-vllm", "in": 0.0, "out": 0.0},
    "claude-x":     {"provider": "anthropic", "in": 3.0, "out": 15.0},   # 100만 토큰당 달러
    "gemini-x":     {"provider": "google",    "in": 0.3, "out": 2.5},
}
ledger = {}

def to_provider(req, provider):
    msgs = req["messages"]
    if provider == "anthropic":   # system 을 따로 빼는 형식
        system = " ".join(m["content"] for m in msgs if m["role"] == "system")
        return {"system": system, "messages": [m for m in msgs if m["role"] != "system"]}
    return {"messages": msgs}      # vLLM·OpenAI 호환은 그대로

def route(service_id, req, usage):
    r = ROUTES[req["model"]]
    body = to_provider(req, r["provider"])
    cost = (usage[0] * r["in"] + usage[1] * r["out"]) / 1e6
    ledger[service_id] = ledger.get(service_id, 0) + cost
    return r["provider"], sorted(body)

req = {"model": "claude-x", "messages": [{"role": "system", "content": "요약해"}, {"role": "user", "content": "글"}]}
print(route("search", req, (2000, 300)))
print(route("search", {**req, "model": "gpt-oss-120b"}, (2000, 300)))
print(route("feed", {**req, "model": "gemini-x"}, (50000, 1000)))
print({k: round(v, 4) for k, v in ledger.items()})
# ('anthropic', ['messages', 'system'])
# ('self-hosted-vllm', ['messages'])
# ('google', ['messages'])
# {'search': 0.0105, 'feed': 0.0175}

# 형식이 정해진 설정: 오타·없는 선택지를 실행 전에 잡는다 (protobuf 대신 파이썬 표준만으로 흉내)
from dataclasses import dataclass, fields
from enum import Enum


class Sampling(Enum):
    RANDOM = "RANDOM"
    STRATIFIED = "STRATIFIED"


@dataclass
class TrainConfig:
    sampling: Sampling
    sample_ratio: float


def load(d):
    extra = set(d) - {f.name for f in fields(TrainConfig)}
    if extra:
        raise ValueError(f"모르는 칸: {extra}")
    return TrainConfig(Sampling(d["sampling"]), float(d["sample_ratio"]))


for cfg in ({"sampling": "STRATIFIED", "sample_ratio": "0.1"},
            {"sampling": "STRATIFED", "sample_ratio": 0.1},
            {"sampling": "RANDOM", "sample_ratoi": 0.1}):
    try:
        print("OK ", load(cfg))
    except (ValueError, KeyError) as e:
        print("ERR", type(e).__name__, e)
# OK  TrainConfig(sampling=<Sampling.STRATIFIED: 'STRATIFIED'>, sample_ratio=0.1)
# ERR ValueError 'STRATIFED' is not a valid Sampling
# ERR ValueError 모르는 칸: {'sample_ratoi'}
